import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.CqGPl1zp.js";const o="/newx-doc/assets/Midjourney-%E7%A7%81%E6%9C%89.BQFu4qC2.png",y=JSON.parse('{"title":"【模型接入】Midjourney","description":"","frontmatter":{},"headers":[],"relativePath":"ai/midjourney.md","filePath":"ai/midjourney.md","lastUpdated":null}'),t={name:"ai/midjourney.md"};function r(p,i,d,l,h,c){return e(),s("div",null,[...i[0]||(i[0]=[n('<h1 id="【模型接入】midjourney" tabindex="-1">【模型接入】Midjourney <a class="header-anchor" href="#【模型接入】midjourney" aria-label="Permalink to &quot;【模型接入】Midjourney&quot;">​</a></h1><p>Midjourney 是一个由位于美国加州旧金山的同名研究实验室开发之人工智能程序，可根据文本生成图像，于 2022 年 7 月 12 日进入公开测试阶段，用户可透过 Discord 的机器人指令进行操作。</p><p>由于 Midjourney 没有直接提供 API 接口，所以大家一般通过 <a href="https://github.com/novicezk/midjourney-proxy/" target="_blank" rel="noreferrer">https://github.com/novicezk/midjourney-proxy/</a> 项目，代理 MidJourney 的 Discord 频道，实现 API 形式调用 AI 绘图。</p><p>也因此，Spring AI 肯定是不集成 Midjourney 的，所以我们实现的 <code>models/midjourney</code> 包下的 MidjourneyApi 类，基于上述的 <code>midjourney-proxy</code> 代理，调用 Midjourney 实现绘图的功能。</p><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>可参考 <a href="https://github.com/novicezk/midjourney-proxy/blob/main/README_CN.md" target="_blank" rel="noreferrer">https://github.com/novicezk/midjourney-proxy/blob/main/README_CN.md</a> 文档，申请相关账号，并搭建 <code>midjourney-proxy</code> 代理。</p><p>不过这个方式比较麻烦，我自己暂时没跑通。我是在 <a href="https://api.holdai.top/register?aff=EcRu" target="_blank" rel="noreferrer">毫秒 API</a> 注册了一个账号，然后通过他们的 API 代理 Midjourney 的。这个是需要付费的，测试的话，建议只小额充值 1-10 块。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。需要填写“密钥” + “自定义 API URL”。如下图所示：</p><p><img src="'+o+`" alt="私有的密钥配置"></p><h2 id="_2-ai-绘图" tabindex="-1">2. AI 绘图 <a class="header-anchor" href="#_2-ai-绘图" aria-label="Permalink to &quot;2. AI 绘图&quot;">​</a></h2><p>后续使用 <a href="./image">《AI 绘图》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的图像模型。</p><p>模型有：<code>niji</code>、<code>midjourney</code> 等等。</p><p>TODO @AI：这里的模型，需要更新下么？</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 MidjourneyApi 对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.midjourney</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    midjourney</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      base-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.holdai.top/mj</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-dZEPiVaNcT3FHhef51996bAa0bC74806BeAb620dA5Da10Bf</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      notify-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://java.nat300.top/admin-api/ai/image/midjourney/notify</span></span></code></pre></div><ul><li><code>base-url</code>：Midjourney 代理的地址，相关的接口文档可见 <a href="https://gpt-best.apifox.cn/doc-3530863" target="_blank" rel="noreferrer">https://gpt-best.apifox.cn/doc-3530863</a></li><li><code>notify-url</code>：Midjourney 生成图片后的回调地址，因为 Midjourney 生成图片是异步的，所以需要回调通知。这个 URL 可以分成两个小部分： <ul><li><code>http://java.nat300.top</code>：你的服务器地址。如果你没外网，可以通过 <a href="./../natapp">《内网穿透》</a> 解决</li><li><code>/admin-api/ai/image/midjourney/notify</code>：对应 AiImageController 的 <code>#midjourneyNotify(...)</code> 方法</li></ul></li></ul><p>另外，考虑到 Midjourney 回调失败的情况，可以把项目的 AiMidjourneySyncJob 定时器类，配置每 1 分钟执行一次，检查是否有未回调的图片。怎么使用定时器，可以参考 <a href="./../job">《定时任务》</a> 文档。</p><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getMidjourneyApi()</code> 方法，获取对应的 MidjourneyApi 对象。</p><p>另外，MidjourneyApiTests 里有对应的测试用例，可以参考。</p>`,21)])])}const k=a(t,[["render",r]]);export{y as __pageData,k as default};
